interface InventoryGateway { suspend fun checkStock(sku: String): Stock }

class AmqpInventoryGateway(private val conn: Connection) : InventoryGateway {
    private val pending = ConcurrentHashMap<String, CompletableDeferred<Stock>>()
    override suspend fun checkStock(sku: String): Stock {
        val id = UUID.randomUUID().toString()
        val reply = CompletableDeferred<Stock>()
        pending[id] = reply                 // the consumer completes it on delivery
        conn.publish(sku, correlationId = id, replyTo = inbox)
        return reply.await()                // caller's coroutine suspends, thread freed
    }
}
